from AlgorithmImports import *
import math


class ExactStrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, Market.USA, False
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_last_close = None
        self.spy_yesterday_close = None
        self.spy_yesterday_sma = None

        self.aapl_last_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars

        if bars.ContainsKey(self.spy):
            spy_bar = bars[self.spy]
            self.spy_yesterday_close = self.spy_last_close
            self.spy_yesterday_sma = (
                self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            )
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_last_close = spy_bar.Close

        if bars.ContainsKey(self.aapl):
            aapl_bar = bars[self.aapl]

            if self.aapl_last_close is not None:
                if aapl_bar.Close < self.aapl_last_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.aapl_last_close = aapl_bar.Close

        if self.IsWarmingUp:
            return

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if (
            not self.spy_sma.IsReady
            or self.spy_yesterday_close is None
            or self.spy_yesterday_sma is None
            or not self.aapl_rsi.IsReady
        ):
            return

        spy_bar = bars[self.spy]
        aapl_bar = bars[self.aapl]

        self._run_strategy_a(spy_bar)
        self._run_strategy_b(aapl_bar)

    def _run_strategy_a(self, spy_bar):
        if self.Transactions.GetOpenOrders(self.spy):
            return

        lot_shares = int(self.Portfolio[self.spy].Quantity)
        crosses_above = (
            self.spy_yesterday_close <= self.spy_yesterday_sma
            and spy_bar.Close > self.spy_sma.Current.Value
        )
        crosses_below = (
            self.spy_yesterday_close >= self.spy_yesterday_sma
            and spy_bar.Close < self.spy_sma.Current.Value
        )

        if lot_shares > 0:
            if crosses_below:
                self.MarketOrder(self.spy, -lot_shares)
            return

        if crosses_above:
            shares = int(
                math.floor(
                    (self.Portfolio.TotalPortfolioValue * 0.40) / spy_bar.Close
                )
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares)

    def _run_strategy_b(self, aapl_bar):
        if self.Transactions.GetOpenOrders(self.aapl):
            return

        lot_shares = int(self.Portfolio[self.aapl].Quantity)

        if lot_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -lot_shares)
            return

        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            shares = int(math.floor(20_000 / aapl_bar.Close))
            if shares > 0:
                self.MarketOrder(self.aapl, shares)
