class ParallelDailyStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_close_history = RollingWindow[float](2)
        self.spy_sma_history = RollingWindow[float](2)

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        self._update_market_state(data)

        if not all(
            data.Bars.ContainsKey(symbol) and data.Bars[symbol] is not None
            for symbol in self.symbols
        ):
            return

        if not self._rules_ready():
            return

        self._run_strategy_a()
        self._run_strategy_b()

    def _update_market_state(self, data: Slice):
        if data.Bars.ContainsKey(self.spy):
            bar = data.Bars[self.spy]
            if bar is not None:
                self.spy_sma.Update(bar.EndTime, bar.Close)
                self.spy_close_history.Add(float(bar.Close))

                if self.spy_sma.IsReady:
                    self.spy_sma_history.Add(float(self.spy_sma.Current.Value))

        if data.Bars.ContainsKey(self.aapl):
            bar = data.Bars[self.aapl]
            if bar is not None:
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

                if self.previous_aapl_close is not None and bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                self.previous_aapl_close = bar.Close

    def _rules_ready(self):
        return (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.spy_close_history.Count == 2
            and self.spy_sma_history.Count == 2
            and self.previous_aapl_close is not None
        )

    def _run_strategy_a(self):
        spy_quantity = self.Portfolio[self.spy].Quantity

        if spy_quantity == 0:
            crossed_above = (
                self.spy_close_history[1] <= self.spy_sma_history[1]
                and self.spy_close_history[0] > self.spy_sma_history[0]
            )

            if crossed_above:
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
        else:
            crossed_below = (
                self.spy_close_history[1] >= self.spy_sma_history[1]
                and self.spy_close_history[0] < self.spy_sma_history[0]
            )

            if crossed_below:
                self.MarketOrder(self.spy, -spy_quantity)

    def _run_strategy_b(self):
        aapl_quantity = self.Portfolio[self.aapl].Quantity

        if aapl_quantity == 0:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                close = self.Securities[self.aapl].Price
                shares = int(20_000 / close)

                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
        elif self.aapl_rsi.Current.Value > 60:
