from collections import deque
from decimal import Decimal


class IndependentSlotsStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = data.Bars

        # Keep market-state calculations current for every available bar.
        if bars.ContainsKey(self.spy):
            self.spy_closes.append(Decimal(str(bars[self.spy].Close)))

        if bars.ContainsKey(self.aapl):
            self._update_aapl_state(Decimal(str(bars[self.aapl].Close)))

        # A missing bar for any subscribed ticker prevents all rule evaluation.
        for symbol in self.symbols.values():
            if not bars.ContainsKey(symbol):
                return

        # SMA cross evaluation needs today's and yesterday's full 100-day SMAs.
        if len(self.spy_closes) < 101 or self.aapl_rsi is None:
            return

        spy_values = list(self.spy_closes)
        yesterday_close = spy_values[-2]
        today_close = spy_values[-1]
        yesterday_sma = sum(spy_values[-101:-1]) / Decimal(100)
        today_sma = sum(spy_values[-100:]) / Decimal(100)

        spy_crosses_above = yesterday_close <= yesterday_sma and today_close > today_sma
        spy_crosses_below = yesterday_close >= yesterday_sma and today_close < today_sma

        # Slot 1: Strategy A
        if self.strategy_a_shares > 0:
            if spy_crosses_below:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif spy_crosses_above:
            shares = int(
                (self.Portfolio.TotalPortfolioValue * Decimal("0.40")) / today_close
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares

        # Slot 2: Strategy B
        if self.strategy_b_shares > 0:
            if self.aapl_rsi > Decimal("60"):
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif self.aapl_red_streak >= 3:
            aapl_close = Decimal(str(bars[self.aapl].Close))
            purchase_amount = Decimal("20000")

            if self.Portfolio.Cash >= purchase_amount:
                shares = int(purchase_amount / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

    def _update_aapl_state(self, close):
        if self.aapl_previous_close is None:
            self.aapl_previous_close = close
            return

        change = close - self.aapl_previous_close

        if close < self.aapl_previous_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        gain = max(change, Decimal(0))
        loss = max(-change, Decimal(0))

        if self.rsi_average_gain is None:
            self.rsi_seed_gains.append(gain)
            self.rsi_seed_losses.append(loss)

            if len(self.rsi_seed_gains) == self.rsi_period:
                self.rsi_average_gain = sum(self.rsi_seed_gains) / Decimal(self.rsi_period)
                self.rsi_average_loss = sum(self.rsi_seed_losses) / Decimal(self.rsi_period)
                self.aapl_rsi = self._calculate_rsi()
        else:
            period = Decimal(self.rsi_period)
            self.rsi_average_gain = (
                (self.rsi_average_gain * (period - 1)) + gain
            ) / period
            self.rsi_average_loss = (
                (self.rsi_average_loss * (period - 1)) + loss
            ) / period
            self.aapl_rsi = self._calculate_rsi()

        self.aapl_previous_close = close

    def _calculate_rsi(self):
        if self.rsi_average_loss == 0:
            return Decimal(100)

        if self.rsi_average_gain == 0:
            return Decimal(0)

        relative_strength = self.rsi_average_gain / self.rsi_average_loss
        return Decimal(100) - (Decimal(100) / (Decimal(1) + relative_strength))
