        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # 101 values are needed to compare today's 100-day SMA to yesterday's.
        self.spy_closes = RollingWindow[float](101)

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        # Market-state quantities are updated whenever the relevant bar exists.
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.Add(data.Bars[self.spy].Close)

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_bar.Close

        # Skip all rule evaluation unless every subscribed ticker has today's bar.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        # Do not trade until every indicator/window used by a rule is fully formed.
        if not self.spy_closes.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        spy_crosses_above = (
            self.spy_closes[1] <= spy_sma_yesterday
            and spy_bar.Close > spy_sma_today
        )
        spy_crosses_below = (
            self.spy_closes[1] >= spy_sma_yesterday
            and spy_bar.Close < spy_sma_today
        )

        # Slot 1: Strategy A
        if not self._has_open_order(self.spy):
            if self.Portfolio[self.spy].Quantity == 0:
                if spy_crosses_above:
                    self.SetHoldings(self.spy, 0.40, tag="Strategy A Buy")
            elif spy_crosses_below:
                self.Liquidate(self.spy, tag="Strategy A Sell")

        # Slot 2: Strategy B
        if not self._has_open_order(self.aapl):
